        public static int HeaderLength(byte field)
        {
            var (frame, header) = Find(field);

            switch (header)
            {
                case HeaderType.NoData:
                    return 0;
                case HeaderType.Short:
                    return 4; //TODO switch between 4 for non wireless and 9 for wireless
                case HeaderType.Long:
                    return 12;
                case HeaderType.ExtendedLinkLayer:
                    switch (frame)
                    {
                        case FrameType.ExtendedLinkLayerTwoBytes:
                            return 2;
                        case FrameType.ExtendedLinkLayerEightBytes:
                            return 8;
                        case FrameType.ExtendedLinkLayerTenBytes:
                            return 10;
                        case FrameType.ExtendedLinkLayerSixteenBytes:
                            return 16;
                    }

                    break;
            }

            // Should never go here!
            return -1;
        }
    }

private void ParseDate(in DataField datafield)
{
    var mapped = (TimeMask)datafield;
    switch (mapped)
    {
        case TimeMask.Date:
            Unit = Unit.Date;
            break;
        case TimeMask.DateTime:
            Type = PrimaryValueInformation.DateTime;
            Unit = Unit.DateTime;
            break;
        case TimeMask.TimeExtended:
            Type = PrimaryValueInformation.ExtendedTime;
            Unit = Unit.DateTime;
            break;
        case TimeMask.DateTimeExtended:
            Type = PrimaryValueInformation.ExtendedDateTime;
            Unit = Unit.DateTimeSecondary;
            break;
    }
}

